mapper.select:
SELECT id, train_id, travel_date, seat_type, from_station_order, to_station_order,
       total_count, remaining_count, price, version, updated_at
FROM seat_inventory
WHERE train_id = #{trainId}
  AND travel_date = #{travelDate}
  AND seat_type = #{seatType}
  AND from_station_order >= #{fromOrder}
  AND to_station_order <= #{toOrder}
ORDER BY from_station_order
FOR UPDATE

mapper.update:
UPDATE seat_inventory
SET remaining_count = remaining_count - 1,
    version = version + 1
WHERE train_id = #{trainId}
  AND travel_date = #{travelDate}
  AND seat_type = #{seatType}
  AND from_station_order >= #{fromOrder}
  AND to_station_order <= #{toOrder}
  AND remaining_count >= 1
